import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"震","description":"周易集解 - 震","frontmatter":{"title":"震","description":"周易集解 - 震"},"headers":[],"relativePath":"classics/jijie/051.md","filePath":"classics/jijie/051.md"}'),l={name:"classics/jijie/051.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="震" tabindex="-1">震 <a class="header-anchor" href="#震" aria-label="Permalink to “震”">​</a></h1><h2 id="震-1" tabindex="-1">震 <a class="header-anchor" href="#震-1" aria-label="Permalink to “震”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>震，亨。震來虩虩，笑言啞啞，震驚百裡，不喪匕鬯。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：主器者莫若長子，故受之以震。震者，動也。</p><p>崔憬曰：鼎所以烹飪，享於上帝。主此器者，莫若冡嫡，以為其祭主也，故｢言主器者莫若長子｣也。</p><p>鄭玄曰：震為雷。雷，動物之氣也。雷之發聲，猶人君出政教以動中國之人也。故謂之震。人君有善聲教，則嘉會之禮通矣。</p><p>虞翻曰：臨二之四，天地交，故｢通｣。虩虩謂四也。來應初命，四變而來應已。四失位多懼，故｢虩虩｣。之內曰來也。</p><p>虞翻曰：啞啞，笑且言，謂初也。得正有則，故｢笑言啞啞，後有則也｣。</p><p>虞翻曰：謂陽從臨二。陰為百二十，舉其大數，故當震百裡也。坎為棘匕。上震為鬯。坤為喪。二上之坤，成震體坎，得其匕鬯，故｢不喪匕鬯｣也。</p><p>鄭玄曰：雷發聲聞於百裡，古者諸侯之象。諸侯出教令，能警戒其國。內則守其宗廟社稷，為之祭主，不亡匕與鬯也。人君於祭之禮，匕牲體薦鬯而已，其餘不親也。升牢於俎，君匕之，臣載之。鬯，秬酒，芬芳修鬯，因名焉。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：震，亨，震來虩虩，恐致福也。笑言啞啞，後有則也。震驚百裡，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：懼變承五應初，故｢恐致福也｣。</p><p>虞翻曰：則，法也。坎為則也。</p><p>虞翻曰：遠謂四，近謂初。震為百，謂四齣驚遠，初應懼近也。</p><p>虞翻曰：為五齣之正。震為守，艮為宗廟社稷，長子主祭器，故｢以為祭主也｣。</p><p>乾寶曰：周木德，震之正象也。為殷諸侯。殷諸侯之制，其地百裡。是以文王小心翼翼，昭事上帝，聿懷多福，厥德不回，以受方國，故以百裡而臣諸侯也。為諸侯，故主社稷。為長子，而為祭主也。祭禮薦陳甚多，而經獨言不喪匕鬯者，匕牲體，薦鬯酒，人君所自親也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：洊雷震，君子以恐懼修省。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：君子謂臨二。二出之坤四，體以修身，坤為身。二之四，以陽照坤，故｢以恐懼修省｣。老子曰：修之身，德乃真也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，震來虩虩，後笑言啞啞，吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：虩虩謂四也。初位在下，故言｢後笑言啞啞｣。得位，｢吉｣故也。</p><p>乾寶曰：得震之正，首震之象者。震來虩虩，羑里之厄也。笑言啞啞，後受方國也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震來虩虩，恐致福也。笑言啞啞，後有則也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：陽稱福。</p><p>虞翻曰：得正，故｢有則也｣。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，震來厲，億喪貝，躋於九陵，勿逐，七日得。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：厲，危也。乘剛，故厲。億，惜辭也。坤為喪。三動離為蠃蚌，故稱貝。在艮山下，故稱陵。震為足，足乘初九故｢躋於九陵｣。震為逐，謂四已體復象，故｢喪貝勿逐｣。三動時離為日，震數七，故｢七日得｣者也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震來厲，乘剛也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：六二木爻，震之身也。得位無應，而以乘剛為危。此託文王積德累功，以被囚為禍也。故曰｢震來厲｣。億，歎辭也。貝，寶貨也。產乎東方，行乎大塗也。此以喻紂拘文王，閎夭之徒。乃於江淮之浦，求盈箱之貝，而以賂紂也。故曰｢億喪貝｣。貝，水物，而方升於九陵。今雖喪之，猶外府也。故曰｢勿逐，七日得｣。七日得者，七年之日也。故《書》曰：誕保文武受命，惟七年，是也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，震蘇蘇，震行無眚。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震蘇蘇，位不當也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：死而復生，稱蘇。三死坤中，動出得正，震為生，故｢蘇蘇｣。坎為眚，三出得正，坎象不見，故｢無眚｣。《春秋傳》曰：晉獲秦諜，六日而蘇也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，震遂泥。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：坤土得雨為泥。位在坎中，故｢遂泥｣也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震遂泥，未光也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：在坎陰中，與屯五同義，故｢未光也｣。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，震，往來厲，億，無喪有事。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：往謂乘陽，來謂應陰；失位乘剛，故｢往來厲｣也。</p><p>虞翻曰：坤為喪也。事謂祭祀之事。出而體隨，王享於西山，則可以守宗廟社稷為祭主，故｢無喪有事｣也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震往來厲，危行也。其事在中，大無喪也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：乘剛山頂，故｢危行也｣。</p><p>虞翻曰：動出得正，故｢無喪｣。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：上謂四也。欲之三，隔坎，故｢震索索｣。三已動，應在離，故｢矍矍｣者也。</p><p>虞翻曰：上得位，震為徵，故徵兇。四變時，坤為躬。鄰謂五也。四上之五，震東兌西，故稱鄰。之五得正，故｢不於其躬於其鄰」。無咎，謂三已變，上應三。震為言，故｢婚媾有言｣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：震索索，中未得也。雖兇無咎，畏鄰戒也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：四未之五，故｢中未得也｣。</p><p>虞翻曰：謂五正位，已乘之逆，畏鄰戒也。</p>',76)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
